    const commit = git(['commit-tree', git(['write-tree']), '-p', remote || sourceCommit, '-m', `Publish static build for issue #${issue}\n\nRun: ${run}\nAttempt: ${attempt}\nGeneration: ${generation}\nSource: ${sourceCommit}`])
